    static String view(){return "package android.view;import java.util.*;import android.content.Context;import android.content.res.Resources;import android.view.accessibility.AccessibilityNodeInfo;public class View{public static final int LAYER_TYPE_SOFTWARE=1;private final Context context;private int w=292,h=64;private boolean enabled=true,longClickable;public String description;public List<Long> callbackDelays=new ArrayList<>();public List<Runnable> callbacks=new ArrayList<>();public View(Context c){context=c;}public Context getContext(){return context;}public Resources getResources(){return context.getResources();}public int getWidth(){return w;}public int getHeight(){return h;}public void size(int width,int height){w=width;h=height;}public void setFocusable(boolean v){}public void setClickable(boolean v){}public void setLayerType(int t,Object p){}public void setContentDescription(String s){description=s;}public void setTooltipText(String s){}public void invalidate(){}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public boolean isLongClickable(){return longClickable;}public void setLongClickable(boolean v){longClickable=v;}public boolean performLongClick(){return true;}public interface OnClickListener{void onClick(View v);}private OnClickListener click;public void setOnClickListener(OnClickListener l){click=l;}public boolean isFocused(){return false;}public boolean isPressed(){return false;}protected void drawableStateChanged(){}public boolean performClick(){if(click!=null)click.onClick(this);return true;}public boolean performHapticFeedback(int n){return true;}public ViewParent getParent(){return null;}public void sendAccessibilityEvent(int n){}public boolean postDelayed(Runnable r,long ms){callbackDelays.add(ms);callbacks.add(r);return true;}public void removeCallbacks(Runnable r){callbacks.remove(r);}public void fireHeld(){for(Runnable r:new ArrayList<>(callbacks))r.run();}protected void onDraw(android.graphics.Canvas c){}protected void onDetachedFromWindow(){}public boolean onTouchEvent(MotionEvent e){return false;}public boolean onKeyDown(int k,KeyEvent e){return false;}public void onInitializeAccessibilityNodeInfo(AccessibilityNodeInfo i){}public boolean performAccessibilityAction(int a,android.os.Bundle b){return a==16&&performClick();}}";}
    static String animator(){return "package android.animation;import java.util.*;public class ValueAnimator extends Animator{public static boolean animationsEnabled=true;public static boolean areAnimatorsEnabled(){return animationsEnabled;}public interface AnimatorUpdateListener{void onAnimationUpdate(ValueAnimator a);}private float from,to,value;private boolean running;private AnimatorUpdateListener update;private AnimatorListenerAdapter listener;static List<ValueAnimator> all=new ArrayList<>();public static ValueAnimator ofFloat(float a,float b){ValueAnimator v=new ValueAnimator();v.from=v.value=a;v.to=b;all.add(v);return v;}public void setDuration(long n){}public void setInterpolator(Object i){}public void addUpdateListener(AnimatorUpdateListener l){update=l;}public void addListener(AnimatorListenerAdapter l){listener=l;}public Object getAnimatedValue(){return Float.valueOf(value);}public boolean isRunning(){return running;}public void start(){running=true;}public void cancel(){if(!running)return;running=false;if(listener!=null)listener.onAnimationEnd(this);}public static void finishAll(){for(ValueAnimator a:new ArrayList<>(all))if(a.running){a.value=a.to;if(a.update!=null)a.update.onAnimationUpdate(a);a.running=false;if(a.listener!=null)a.listener.onAnimationEnd(a);}}public static void half(){for(ValueAnimator a:new ArrayList<>(all))if(a.running){a.value=(a.from+a.to)/2;if(a.update!=null)a.update.onAnimationUpdate(a);}}}";}
    static String probe(){return "package com.silverroom.camera;import android.content.Context;import android.view.*;import android.animation.ValueAnimator;import android.graphics.Canvas;import android.view.accessibility.AccessibilityNodeInfo;import java.util.*;public final class ReelProbe{static List<String> passed=new ArrayList<>();static void check(boolean v,String n){if(!v)throw new AssertionError(n);passed.add(n);}static class Harness{Context c=new Context();FilmWheel wheel=new FilmWheel(c);int repeats,changes;Harness(){wheel.films(Arrays.asList(0,1,2,3,4),2);wheel.listener=id->changes++;wheel.reselected=()->repeats++;}void event(int action,float x){wheel.onTouchEvent(new MotionEvent(action,x,32));}void tap(float x){event(0,x);event(1,x);}float center(){return wheel.getWidth()/2f;}}public static List<String> run(){"+
        "Harness h=new Harness();h.tap(h.center()+h.wheel.pitch());check(h.changes==1&&h.repeats==0&&h.wheel.state.selected()==3,\"Adjacent film tap applies exactly once without opening strength\");ValueAnimator.finishAll();h.tap(h.center());check(h.repeats==1&&h.changes==1,\"Retapping the settled selected film opens strength once without reapplying the look\");"+
        "h=new Harness();h.tap(h.center()+h.wheel.pitch());h.tap(h.center());check(h.repeats==0,\"A tap interrupting tap-settle animation never opens the strength panel\");ValueAnimator.finishAll();h.tap(h.center());check(h.repeats==1,\"A later settled tap remains available after animation interruption\");"+
        "h=new Harness();h.event(0,h.center());h.event(2,h.center()-h.wheel.pitch()*.7f);h.event(1,h.center()-h.wheel.pitch()*.7f);ValueAnimator.finishAll();check(h.repeats==0&&h.changes>0,\"Dragging through a detent and releasing switches films without an accidental strength popup\");"+
        "h=new Harness();h.event(0,h.center());h.event(2,h.center()-h.wheel.pitch()*.2f);h.event(1,h.center()-h.wheel.pitch()*.2f);ValueAnimator.half();h.tap(h.center());check(h.repeats==0,\"A touch interrupting inertia or fractional settling cannot masquerade as a settled retap\");ValueAnimator.finishAll();"+
        "h=new Harness();h.event(0,h.center());h.event(3,h.center());h.event(1,h.center());check(h.repeats==0,\"Cancelled gestures cannot open strength\");"+
        "h=new Harness();h.event(0,h.center());h.event(5,h.center());h.event(1,h.center());check(h.repeats==0,\"A second finger cancels the repeat-click gesture\");"+
        "h=new Harness();h.wheel.setLongClickable(true);h.event(0,h.center());h.wheel.fireHeld();h.event(1,h.center());check(h.repeats==0,\"Releasing a completed long press cannot trigger strength\");"+
        "h=new Harness();h.wheel.setEnabled(false);h.tap(h.center());h.wheel.performAccessibilityAction(FilmWheel.ACTION_ADJUST_STRENGTH,null);check(h.repeats==0&&h.changes==0,\"Disabled capture-state reels reject touch and accessibility adjustment\");"+
        "h=new Harness();h.wheel.strength(.7f);Canvas canvas=new Canvas();h.wheel.onDraw(canvas);check(canvas.texts.contains(\"70%\")&&h.wheel.description.contains(\"70%\")&&canvas.texts.stream().filter(s->s.endsWith(\"%\")).count()==1,\"Only the selected card draws the shared strength and announces its current percentage\");"+
        "AccessibilityNodeInfo info=new AccessibilityNodeInfo();h.wheel.onInitializeAccessibilityNodeInfo(info);check(info.actions.stream().anyMatch(a->a.id==FilmWheel.ACTION_ADJUST_STRENGTH&&a.label.contains(\"强度\")),\"Selected film exposes an explicitly labeled accessibility strength action\");h.wheel.performAccessibilityAction(FilmWheel.ACTION_ADJUST_STRENGTH,null);check(h.repeats==1,\"Accessibility action opens the same strength callback\");h.wheel.onKeyDown(KeyEvent.KEYCODE_ENTER,new KeyEvent());check(h.repeats==2,\"Keyboard activation opens current-film strength\");"+
        "boolean widths=true,textBounds=true,themes=true;for(int mode=0;mode<2;mode++){AppTheme.select(mode);for(int body:new int[]{296,336,388,456})for(float font:new float[]{1,1.3f,2}){h=new Harness();h.c.resources.metrics.scaledDensity=font;h.wheel.size(body-96,64);h.wheel.strength(.35f);Canvas draw=new Canvas();h.wheel.onDraw(draw);float pitch=h.wheel.pitch();widths&=pitch>=80&&pitch<=88;if(body>=336)widths&=(body-96)/pitch>=3;for(float width:draw.widths)textBounds&=width<=pitch-12+.01f;themes&=draw.texts.contains(\"35%\");}}check(widths,\"Reel spacing stays within 80-88dp and exposes at least three slots at common phone widths\");check(textBounds,\"All rendered title and subtitle traces fit their slot at normal and enlarged font scales\");check(themes,\"Both theme modes retain the selected percentage and layout density\");"+
        "LensWheel lens=new LensWheel(new Context());boolean[] enabled={true,true,true,true,true,true,true};lens.availability(enabled,new String[]{\"光学\",\"光学\",\"裁切\",\"裁切\",\"光学\",\"裁切\",\"裁切\"},1,false);final int[] unexpected={0},changes={0},blocked={0};lens.reselected=()->unexpected[0]++;lens.listener=id->changes[0]++;float center=lens.getWidth()/2f;lens.onTouchEvent(new MotionEvent(0,center,26));lens.onTouchEvent(new MotionEvent(1,center,26));AccessibilityNodeInfo li=new AccessibilityNodeInfo();lens.onInitializeAccessibilityNodeInfo(li);check(unexpected[0]==0&&changes[0]==0&&li.actions.stream().noneMatch(a->a.id==FilmWheel.ACTION_ADJUST_STRENGTH)&&lens.pitch()==72,\"Retapping a focal length retains the original 72dp lens interaction and has no strength action\");enabled[2]=false;lens.availability(enabled,new String[7],1,false);lens.blocked=mm->blocked[0]++;lens.onTouchEvent(new MotionEvent(0,center+72,26));lens.onTouchEvent(new MotionEvent(1,center+72,26));check(blocked[0]==1&&changes[0]==0&&lens.state.selected()==1,\"Tapping an unavailable focal length still reports blocked optics without changing the lens\");"+
        "h=new Harness();h.wheel.strength(0);Canvas zero=new Canvas();h.wheel.onDraw(zero);h.wheel.strength(1);Canvas full=new Canvas();h.wheel.onDraw(full);check(zero.texts.contains(\"0%\")&&full.texts.contains(\"100%\"),\"Zero and full-strength labels stay readable without a separate percentage control\");return passed;}}";
    }
